// sketch.ino — ESP32-S3: Создает файл из Base64 и открывает его
#include "USB.h"
#include "USBHIDKeyboard.h"
USBHIDKeyboard Keyboard;

// ВСТАВЬ СЮДА ВСЮ СТРОКУ BASE64 ОТ ТВОЕГО JPG (она будет очень длинной)
// Если строка слишком длинная для Arduino IDE, придется разбить её на части.
const char* B64_DATA = "";

void setup() {
  pinMode(0, INPUT_PULLUP);
  Keyboard.begin();
  USB.begin();
  delay(3000);
  while (digitalRead(0) == HIGH) delay(10);

  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(60); Keyboard.releaseAll(); delay(600);

  // 1. Создаем временный файл с картинкой через PowerShell
  // Команда декодирует строку и сохраняет как .jpg
  Keyboard.print("powershell -NoProfile -WindowStyle Hidden -Command \"\$b='");
  Keyboard.print(B64_DATA);
  Keyboard.print("'; [IO.File]::WriteAllBytes('C:\\Temp\\img_out.jpg',[Convert]::FromBase64String(\$b)); Start-Process 'C:\\Temp\\img_out.jpg'\"");

  Keyboard.press(KEY_RETURN); delay(100); Keyboard.releaseAll();
}

void loop() {}
